steps.run:
set -euo pipefail
manifest="ci-build-artifact/${{ steps.cell.outputs.build_artifact }}.manifest.json"
[ -f "$manifest" ] || { echo "the build artifact carries no manifest at $manifest" >&2; exit 1; }
{
  echo "digest=$(jq -er '.digest' "$manifest")"
  echo "archive_name=$(jq -er '.archive.file' "$manifest")"
  echo "download_seconds=$(( $(date +%s) - ${{ steps.transfer.outputs.epoch }} ))"
} >>"$GITHUB_OUTPUT"

with.script:
const owner = require(`${process.env.GITHUB_WORKSPACE}/scripts/ci/artifacts/produce.cjs`);
if (!await owner.produceOwner(owner.hostedOptions())) {
  core.setFailed('One or more package builds failed or could not be published');
}

const root = process.env.GITHUB_WORKSPACE;
const {hostedOptions} = require(`${root}/scripts/ci/artifacts/produce.cjs`);
const {finalizeOwner} = require(`${root}/scripts/ci/artifacts/publish.cjs`);
if (!await finalizeOwner(hostedOptions())) {
  core.setFailed('One or more package builds could not be published');
}

env.RESULTS:
validation:${{ needs.validation.result }}
scope:${{ needs.scope.result }}
preflight:${{ needs.preflight.result }}
build:${{ needs.build.result }}
area-ci:${{ needs.area-ci.result }}
area-drift:${{ needs.area-drift.result }}
